import { useState } from 'react'
import './TransferHistory.css'

const entries=[
 {id:'salary-1',date:'2026.11.26',time:'17:10',sender:'이온농장',enSender:'Lee On Farm',job:'사과 수확',enJob:'Apple harvesting',amount:120000,account:'1002-•••-••0370'},
 {id:'salary-2',date:'2026.11.25',time:'17:05',sender:'진위 딸기농장',enSender:'Jinwi Strawberry Farm',job:'딸기 수확',enJob:'Strawberry harvesting',amount:110000,account:'1002-•••-••0370'},
 {id:'salary-3',date:'2026.11.23',time:'17:20',sender:'이온농장',enSender:'Lee On Farm',job:'사과 선별',enJob:'Apple sorting',amount:120000,account:'1002-•••-••0370'},
]
export default function TransferHistory({english=false,onClose}:{english?:boolean;onClose:()=>void}){
 const [selected,setSelected]=useState<typeof entries[number]|null>(null)
 return <div className="salary-history" lang={english?'en':'ko'}><header><button aria-label={english?'Back':'뒤로'} onClick={()=>selected?setSelected(null):onClose()}>‹</button><h1>{selected?(english?'Transfer Details':'이체 상세 내역'):(english?'Transfer History':'이체 내역 확인')}</h1></header><main><p className="salary-history-demo">{english?'Sample salary transfers · No bank connection':'급여 이체 예시 · 실제 은행 조회 내역이 아니에요'}</p>{selected?<><section className="salary-history-receipt"><span className="salary-history-check">✓</span><h2>{english?'Salary received':'급여 수령 완료'}</h2><strong>{selected.amount.toLocaleString()}{english?' KRW':'원'}</strong><dl>{[[english?'Sender':'보낸 분',english?selected.enSender:selected.sender],[english?'Work':'근무 내용',english?selected.enJob:selected.job],[english?'Work date':'근무일',selected.date],[english?'Transfer time':'이체 일시',`${selected.date} ${selected.time}`],[english?'Receiving account':'급여 수령 계좌',selected.account],[english?'Status':'처리 상태',english?'Completed (sample)':'완료 (예시)']].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></section><button className="salary-history-confirm" onClick={()=>setSelected(null)}>{english?'Back to history':'이체 내역으로'}</button></>:<><section className="salary-history-summary"><span>{english?'Salary received':'받은 급여'}</span><strong>350,000{english?' KRW':'원'}</strong><small>2026.11.01 – 2026.11.30 · {english?'3 transfers':'3건'}</small></section><div className="salary-history-label">{english?'Salary transfer history':'급여 이체 내역'}</div><div className="salary-history-list">{entries.map(entry=><button key={entry.id} onClick={()=>setSelected(entry)}><small>{entry.date} · {entry.time}</small><div><strong>{english?entry.enSender:entry.sender}</strong><b>+{entry.amount.toLocaleString()}{english?' KRW':'원'}</b></div><p>{english?entry.enJob:entry.job} · {english?'Salary':'급여'}<span>›</span></p></button>)}</div></>}</main></div>
}
